#{(function(){
			var others = mascot.manager.getMascotList();
			for(var i=0;i < others.size();i++){
				var o=others.get(i); if(o===mascot) continue;
				var dx=o.anchor.x-mascot.anchor.x;
				var dy=o.anchor.y-mascot.anchor.y;
				if(Math.sqrt(dx*dx+dy*dy) <= Math.round(64 * mascot.currentScale * scaling) && dx >=0) return true;
			} return false;
			})()
			}

